// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    address owner;

    function setUp() public {
        c = new MultiplicatorX4();
        owner = c.Owner();
    }

    function testFuzz_property(uint256 amount, bytes32 payload) public {
        vm.assume(amount < 1 ether);
        address adr = address(new GasGuzzler());
        vm.deal(owner, amount);
        vm.prank(owner);
        bool ok;
        try c.Command{value: amount}(adr, abi.encodePacked(payload)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract GasGuzzler {
    uint256 public x;
    fallback() external payable {
        // a storage write costs far more than the 2300-gas stipend of a bare transfer
        x += 1;
    }
    receive() external payable {
        x += 1;
    }
}
